package com.sobrenaturaldirector.planner.validation;
import java.util.*;import com.sobrenaturaldirector.planner.model.*;import com.sobrenaturaldirector.planner.requirement.PlanRequirement;
public final class PlanValidator {public PlanValidation validate(DirectorPlan p){List<String>e=new ArrayList<String>();Set<String>ids=new HashSet<String>();for(PlanStep s:p.getSteps())if(!ids.add(s.getStepId()))e.add("DUPLICATE_STEP_ID");Set<String>known=ids;for(PlanStep s:p.getSteps())for(String d:s.getDependencies())if(!known.contains(d))e.add("MISSING_DEPENDENCY:"+d);Map<String,List<String>>g=new HashMap<String,List<String>>();for(PlanStep s:p.getSteps())g.put(s.getStepId(),s.getDependencies());Set<String>active=new HashSet<String>(),done=new HashSet<String>();for(String id:ids)if(cycle(id,g,active,done))e.add("DEPENDENCY_CYCLE");Set<String>reqIds=new HashSet<String>();for(PlanRequirement r:p.getRequirements())if(!reqIds.add(r.getId()))e.add("DUPLICATE_REQUIREMENT_ID");if(p.getSteps().size()>DirectorPlan.MAX_STEPS||p.getRequirements().size()>DirectorPlan.MAX_REQUIREMENTS)e.add("BOUND_EXCEEDED");return new PlanValidation(e);}private boolean cycle(String id,Map<String,List<String>>g,Set<String>a,Set<String>d){if(d.contains(id))return false;if(!a.add(id))return true;List<String>deps=g.get(id);if(deps!=null)for(String x:deps)if(cycle(x,g,a,d))return true;a.remove(id);d.add(id);return false;}}
